{
  "hypotheses": [
    {
      "table": "fda_snapshot.recalls",
      "column": "openfda_product_ndc",
      "transform": "identity",
      "rationale": "The column name explicitly indicates it holds product NDC codes from the FDA's openfda metadata field. The hospital's format is NDC11, and this field is designed to contain NDC identifiers, making it the most direct match without requiring structural transformation."
    },
    {
      "table": "fda_snapshot.recalls",
      "column": "openfda_package_ndc",
      "transform": "identity",
      "rationale": "Similar to the product NDC field, this column is explicitly named as an FDA openfda package NDC identifier. It represents the package-level NDC which, like product NDCs, follows the 11-digit NDC11 format used by the hospital."
    },
    {
      "table": "fda_snapshot.shortages",
      "column": "package_ndc",
      "transform": "strip_hyphens",
      "rationale": "The sample values show NDCs in the standard hyphenated format (5-4-2 segments like \"0009-0225-02\"). The hospital stores NDC11 without hyphens, so stripping hyphens is the necessary transform to convert these values to the hospital's format."
    },
    {
      "table": "fda_snapshot.ndc_packages",
      "column": "product_ndc",
      "transform": "lpad_11",
      "rationale": "The sample values (\"82953-020\", \"45802-042\", \"45802-042\") show NDCs with only 8 digits after removing the hyphen-separated segments. These are likely incomplete NDCs that need left-padding to 11 digits to match the hospital's NDC11 format."
    },
    {
      "table": "fda_snapshot.ndc_packages",
      "column": "package_ndc",
      "transform": "lpad_11",
      "rationale": "The sample values (\"82953-020-01\", \"45802-042-01\", \"45802-042-02\") show package NDCs in 5-4-2 hyphenated format. These need both hyphen removal and digit padding to 11 characters to convert to the hospital's NDC11 format."
    },
    {
      "table": "wholesaler.catalog",
      "column": "ndc",
      "transform": "lpad_11",
      "rationale": "The sample values (\"143926901\", \"25021070102\", \"31722030725\") show varying lengths - some 9 digits, some 11 digits. The transform lpad_11 would standardize all to exactly 11 digits by left-padding shorter codes, which matches the hospital's NDC11 format requirement."
    }
  ]
}

